def rule(ctx):
    actions = []
    if ctx.available:
        min_hours = min(r.hours for r in ctx.available)
        threshold = 30.0  # allow a robot to lead by up to ~30h before switching

        def key(r):
            over = 1 if r.hours > min_hours + threshold else 0
            # Prefer robots that are within the lead, then those with less remaining
            # budget (closer to maintenance), then fewer hours, fewer duties, and
            # finally earlier opening order for determinism.
            return (over, r.budget, r.hours, r.count, r.idx)

        for r in sorted(ctx.available, key=key):
            actions.append(("reuse", r))

    # New robot preference: keep the genome's type first if it can still be opened,
    # then other types sorted by an efficiency estimate.
    left_types = [k for k in range(len(ctx.types)) if ctx.types[k] is not None and ctx.left[k] > 0]

    def type_score(k):
        t = ctx.types[k]
        overhead = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        return overhead / t['work_time'] + t['maintenance_time'] / t['continue_max_work']

    left_types.sort(key=type_score)

    new_actions = []
    if ctx.left[ctx.gene_type] > 0:
        new_actions.append(("new", ctx.gene_type))
    for k in left_types:
        if k != ctx.gene_type:
            new_actions.append(("new", k))

    return actions + new_actions

