def rule(ctx):
    remaining = ctx.remaining
    capacity = ctx.capacity

    if capacity >= remaining:
        # Enough capacity: balance duty hours and counts, prefer fresh robots.
        def key(r):
            return (r.hours, -r.budget, r.count, r.idx)
    else:
        # Short on capacity: stagger maintenance to keep some robots available.
        # Prefer robots with more hours used / less remaining budget.
        def key(r):
            score = r.hours + 2.0 * r.budget
            return (score, r.count, r.idx)

    sorted_reuse = sorted(ctx.available, key=key)
    actions = [("reuse", r) for r in sorted_reuse]

    # New robot type preference
    candidates = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is None or ctx.left[k] <= 0:
            continue
        t = ctx.types[k]
        work_time = t['work_time']
        single_work = t['single_work_time']
        continue_max = t['continue_max_work']
        fits = 1 if work_time <= remaining else 0
        duties_per_cycle = continue_max / single_work if single_work > 0 else 0
        candidates.append((fits, work_time, duties_per_cycle, k))

    # Sort: fit first, then larger work_time, then more duties per maintenance cycle.
    candidates.sort(key=lambda x: (-x[0], -x[1], -x[2], x[3]))
    for _, _, _, k in candidates:
        actions.append(("new", k))

    return actions

