def rule(ctx):
    remaining = ctx.remaining

    # Reuse: balance duty hours, then prefer robots with less remaining budget
    # to stagger maintenance and avoid simultaneous unavailability.
    def key(r):
        return (r.hours, r.budget, r.count, r.idx)
    sorted_reuse = sorted(ctx.available, key=key)
    actions = [("reuse", r) for r in sorted_reuse]

    # Minimum work_time among types that can still be opened.
    min_work = float('inf')
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            wt = ctx.types[k]['work_time']
            if wt < min_work:
                min_work = wt

    candidates = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is None or ctx.left[k] <= 0:
            continue
        t = ctx.types[k]
        work_time = t['work_time']
        out = t['out_travel_time']
        ret = t['return_travel_time']
        charge = t['charge_time']
        maint = t['maintenance_time']
        cont = t['continue_max_work']
        single = t['single_work_time']

        # Long-run efficiency: work hours per unit time.
        denom = out + work_time + ret + charge
        if cont > 0:
            denom += maint * single / cont
        eff = work_time / denom if denom > 0 else 0

        fits = 1 if work_time <= remaining else 0
        new_rem = remaining - work_time
        if new_rem == 0 or new_rem >= min_work:
            bad_rem = 0
        else:
            bad_rem = 1

        candidates.append((fits, bad_rem, -eff, -work_time, k))

    if not candidates:
        # No type can be opened; suggest the smallest work_time as a last resort.
        best_k = None
        best_wt = float('inf')
        for k in range(len(ctx.types)):
            if ctx.types[k] is None or ctx.left[k] <= 0:
                continue
            wt = ctx.types[k]['work_time']
            if wt < best_wt:
                best_wt = wt
                best_k = k
        if best_k is not None:
            actions.append(("new", best_k))
    else:
        # Sort: fits first, then good remainder, then higher efficiency,
        # then larger work_time, then type index.
        candidates.sort(key=lambda x: (-x[0], x[1], x[2], x[3], x[4]))
        for _, _, _, _, k in candidates:
            actions.append(("new", k))

    return actions

