    if ctx.available:
        min_hours = min(r.hours for r in ctx.available)
        lead_limit = 30.0

        def key(r):
            t = ctx.types[r.type]
            work_time = t['work_time']
            maint_time = t['maintenance_time']
            over = 1 if r.hours > min_hours + lead_limit else 0
            # If maintenance would finish before T, trigger it early (low duties_left).
            # Otherwise avoid triggering it (high duties_left).
            if ctx.remaining > maint_time:
                urgency = r.duties_left
            else:
                urgency = -r.duties_left
            return (over, urgency, r.hours, r.count, -work_time, r.idx)

