        overhead = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        work_time = t['work_time']
        score = overhead / work_time
        if ctx.remaining > t['maintenance_time']:
            score += t['maintenance_time'] / t['continue_max_work']
        if work_time > ctx.remaining:
            score += (work_time - ctx.remaining) / max(1.0, work_time)
        return score

    left_types.sort(key=type_score)

    new_actions = []
    if ctx.types[ctx.gene_type] is not None and ctx.left[ctx.gene_type] > 0:
        new_actions.append(("new", ctx.gene_type))
    for k in left_types:
        if k != ctx.gene_type:
            new_actions.append(("new", k))

    return actions + new_actions

