def rule(ctx):
    types = ctx.types
    left = ctx.left
    remaining = ctx.remaining
    available = ctx.available
    all_robots = ctx.robots

    def w_of(r):
        return types[r.type]['work_time']

    valid_type_indices = [k for k in range(len(types)) if types[k] is not None]
    if not valid_type_indices:
        return []
    all_work_times = [types[k]['work_time'] for k in valid_type_indices]
    min_w = min(all_work_times)

    avg_maint = sum(types[k]['maintenance_time'] for k in valid_type_indices) / len(valid_type_indices)
    avg_work = sum(types[k]['work_time'] for k in valid_type_indices) / len(valid_type_indices)
    T_count = max(1, int(avg_maint / avg_work / 2.0 + 0.5))

    def util(k):
        info = types[k]
        w = info['work_time']
        cmw = info['continue_max_work']
        mt = info['maintenance_time']
        if w <= 0:
            return 0.0
        duties = cmw // w
        if duties <= 0:
            return 0.0
        work_per_cycle = duties * w
        return work_per_cycle / (work_per_cycle + mt) if work_per_cycle + mt > 0 else 0.0

    if not available:
        candidates = [k for k in valid_type_indices if left[k] > 0]
        if not candidates:
            return []
        def type_key(k):
            info = types[k]
            w = info['work_time']
            if remaining < w:
                fit = 3
            else:
                R = remaining - w
                if R == 0:
                    fit = 0
                elif R < min_w:
                    fit = 2
                else:
                    fit = 1
            u = util(k)
            if fit <= 1:
                return (fit, -u, -w, k)
            else:
                return (fit, -u, k)
        candidates.sort(key=type_key)
        return [("new", k) for k in candidates]

    valid = []
    for r in available:
        w = w_of(r)
        if remaining < w:
            continue
        R = remaining - w
        if R == 0 or R >= min_w:
            valid.append(r)
    if not valid:
        valid = available

    if all_robots:
        counts = [r.count for r in all_robots]
        min_count_all = min(counts)
        max_count_all = max(counts)
    else:
        min_count_all = 0
        max_count_all = 0

    if max_count_all - min_count_all >= T_count:
        def sort_key(r):
            w = w_of(r)
            fit = 0 if remaining == w else 1
            return (fit, r.count, r.hours, r.budget, r.idx)
    else:
        def sort_key(r):
            w = w_of(r)
            fit = 0 if remaining == w else 1
            return (fit, r.budget, r.count, r.hours, r.idx)

    sorted_avail = sorted(valid, key=sort_key)
    actions = [("reuse", r) for r in sorted_avail]

    new_types = []
    if ctx.gene_type is not None and types[ctx.gene_type] is not None and ctx.left[ctx.gene_type] > 0:
        new_types.append(ctx.gene_type)
    other_types = [k for k in valid_type_indices if left[k] > 0 and k != ctx.gene_type]
    def new_type_key(k):
        info = types[k]
        w = info['work_time']
        if remaining < w:
            fit = 3
        else:
            R = remaining - w
            if R == 0:
                fit = 0
            elif R < min_w:
                fit = 2
            else:
                fit = 1
        u = util(k)
        if fit <= 1:
            return (fit, -u, -w, k)
        else:
            return (fit, -u, k)
    other_types.sort(key=new_type_key)
    new_types.extend(other_types)
    actions.extend([("new", k) for k in new_types])

    return actions

