def rule(ctx):
    actions = []
    if ctx.available:
        # Fleet stress: high when capacity is barely enough or insufficient
        if ctx.remaining <= 0:
            stress = 1.0
        else:
            ratio = ctx.capacity / ctx.remaining
            stress = 2.0 - ratio
            if stress < 0.0:
                stress = 0.0
            elif stress > 1.0:
                stress = 1.0

        # Balance ordering: prefer robot that, after this duty, has the fewest hours.
        def balance_key(r):
            t = ctx.types[r.type]
            proj_hours = r.hours + (t['work_time'] if t else 0.0)
            return (proj_hours, r.count, r.idx)

        # Stagger ordering: prefer robot closest to maintenance (lowest budget).
        def stagger_key(r):
            return (r.budget, r.hours, r.count, r.idx)

        balance_order = sorted(ctx.available, key=balance_key)
        stagger_order = sorted(ctx.available, key=stagger_key)

        # High stress -> stagger (default), low stress -> balance (default)
        if stress > 0.5:
            default_order = stagger_order
            alt_order = balance_order
        else:
            default_order = balance_order
            alt_order = stagger_order

        # Interleave the two orderings: default[0], alt[0], default[1], alt[1], ...
        interleaved = []
        seen = set()
        max_len = max(len(default_order), len(alt_order))
        for i in range(max_len):
            if i < len(default_order):
                r = default_order[i]
                if r.idx not in seen:
                    interleaved.append(r)
                    seen.add(r.idx)
            if i < len(alt_order):
                r = alt_order[i]
                if r.idx not in seen:
                    interleaved.append(r)
                    seen.add(r.idx)

        for r in interleaved:
            actions.append(("reuse", r))

    # New robot type preference: genome's type first, then by efficiency.
    left_types = [k for k in range(len(ctx.types)) if ctx.types[k] is not None and ctx.left[k] > 0]

    def type_score(k):
        t = ctx.types[k]
        overhead = t['out_travel_time'] + t['return_travel_time'] + t['charge_time']
        maint_term = t['maintenance_time'] / t['continue_max_work'] if t['continue_max_work'] > 0 else 0.0
        return overhead / t['work_time'] + maint_term

    left_types.sort(key=type_score)

    new_actions = []
    if ctx.left[ctx.gene_type] > 0:
        new_actions.append(("new", ctx.gene_type))
    for k in left_types:
        if k != ctx.gene_type:
            new_actions.append(("new", k))

    return actions + new_actions

