    all_work_times = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None:
            all_work_times.append(ctx.types[k]['work_time'])
    min_w = min(all_work_times) if all_work_times else 1.0

    # Tighter balancing threshold for mixed duty lengths (e.g., group M)
    if len(set(all_work_times)) > 1:
        lead_limit = 2.0 * min_w
    else:
        lead_limit = 3.0 * min_w

    available = list(ctx.available)
    min_hours_avail = min(r.hours for r in available) if available else 0.0

    def res_key(r):
        t = ctx.types[r.type]
        w = t['work_time']
        if w > ctx.remaining:
            return (2, 0, 0, 0, 0, 0)
        over = 1 if r.hours > min_hours_avail + lead_limit else 0
        maint_time = t['maintenance_time']
        if ctx.remaining > maint_time:
            urgency = r.budget
        else:
            urgency = -r.budget
        return (over, urgency, r.hours, r.count, -w, r.idx)

    def bal_key(r):
        return (r.hours, r.count, r.idx)

    res_sorted = sorted(available, key=res_key)
    bal_sorted = sorted(available, key=bal_key)

    actions = []
    added = set()

    # First: best resource-efficient choice (default)
    if res_sorted:
        r0 = res_sorted[0]
        actions.append(("reuse", r0))
        added.add(r0.idx)

    # Second: best balance-oriented choice (for useful deviations)
    for r in bal_sorted:
        if r.idx not in added:
            actions.append(("reuse", r))
            added.add(r.idx)
            break

    # Third: next best resource choice
    for r in res_sorted:
        if r.idx not in added:
            actions.append(("reuse", r))
            added.add(r.idx)
            break

    # Remaining in resource order
    for r in res_sorted:
        if r.idx not in added:
            actions.append(("reuse", r))
            added.add(r.idx)

    left_types = [k for k in range(len(ctx.types)) if ctx.types[k] is not None and ctx.left[k] > 0]

